<script>export let form;</script><section class="page form-wrap"><div class="eyebrow">ADOPTION</div><h1>List an animal</h1><p class="sub">Share basic information and let interested people contact you.</p>{#if form?.error}<div class="error">{form.error}</div>{/if}<form class="form" method="POST" enctype="multipart/form-data"><label>Animal</label><select name="animal_type"><option value="dog">Dog</option><option value="cat">Cat</option></select><label>Title</label><input name="title" required maxlength="120" placeholder="e.g. Milo is looking for a loving home"/><label>Description</label><textarea name="description" required placeholder="Age, personality, vaccinations, special needs..."></textarea><label>Location</label><input name="location" required maxlength="160" placeholder="Area / city"/><label>Photo</label><input type="file" name="image" accept="image/*"/><button class="btn primary">Publish adoption listing</button></form></section>
